(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zm-sj-prepa-chir-j4-ide"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zm-sj-prepa-chir-j4-ide\",\n \"titre\": \"Préparation D.E (J) · J4 Chirurgie IDE\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 57,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n   \"sha256\": \"45110ca169c7b815e8c5983cb6aa915440763cce1306bb015109584afb42df7f\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Chirurgie · Prépa D.E J4 (IDE)\",\n     \"slug\": \"prepa-chir-j4-ide\",\n     \"pages\": \"\",\n     \"count\": 57,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Chirurgie\",\n     \"source\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Devant un traumatisme crânien avec signe neurologique ou plaie pénétrante, un scanner est obligatoire d’emblée.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Groupe 3 de Master : TC avec Glasgow < 15, signe neurologique, aggravation ou plaie pénétrante → scanner d’emblée et surveillance neurologique.\\n\\nSource : Neurochirurgie (livret), p. 7 (Groupe 3) ; NEUROCHIRURGIE L3, diapo 30\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__1\",\n       \"num\": \"2\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un traumatisé crânien qui ouvre les yeux de façon spontanée, répond aux piqûres du membre par le retrait et répond aux questions de façon appropriée a un Glasgow de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"12\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"13\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 13\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ouverture spontanée des yeux = 4 ; retrait du membre à la douleur = 4 ; réponse verbale appropriée/orientée = 5. Total : 4 + 4 + 5 = 13.\\n\\nSource : NEUROCHIRURGIE L3, score de Glasgow (diapos 17 à 21)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"On parle de traumatisme crânien grave lorsque le Glasgow est inférieur à 9 après correction des fonctions vitales.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Phrase du cours : « On parle de traumatisme crânien grave lorsque le Glasgow est inférieur à 9 après correction des fonctions vitales » (Glasgow 3 à 8).\\n\\nSource : Neurochirurgie (livret), p. 6\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La hernie abdominale étranglée touche exclusivement les personnes de sexe masculin.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La hernie crurale s’observe surtout chez la femme adulte, la hernie ombilicale de l’adulte aussi ; toutes peuvent s’étrangler.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Hernies – autres sites (diapo 205)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la hernie discale, le signe de Lasègue consiste à réveiller la douleur empêchant la poursuite du mouvement en soulevant progressivement le membre inférieur avec le genou étendu.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le signe de Lasègue est recherché sur le patient couché : l’élévation progressive du membre inférieur, genou tendu, étire les racines comprimées et réveille la douleur sciatique, ce qui arrête le mouvement. Il traduit le conflit disco-radiculaire. (description du signe partiellement hors cours du projet)\\n\\nSource : Neurochirurgie (livret), Sciatalgies / hernie discale (p. 24 et suivantes)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’abcès chaud est une collection purulente aigüe causée par le bacille de Koch.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. L’abcès chaud est dû à des germes pyogènes (staphylocoque, streptocoque…). Le bacille de Koch est le germe de l’abcès froid.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Abcès chaud – étiologies ; Abcès froid – étiologies\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’aplatissement du moignon de l’épaule, avec le coup de hache externe au tiers supérieur du bras est le signe de l’épaulette dans les luxations de l’épaule\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Dans la luxation antéro-interne, l’inspection de face montre l’aplatissement du moignon de l’épaule et la déformation en coup de hache externe au tiers supérieur du bras : c’est le signe de l’épaulette.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Luxation de l’épaule (p. 17-24) ; Traumatologie complet (chirurgie traumatologique et orthopédique), luxation antéro-interne – inspection\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture de Pouteau Colle est une fracture de partie distale du radius ou fracture juxta-articulaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. « La fracture de Pouteau-Colles est la fracture de la partie distale du radius ou fracture classique juxta-articulaire. »\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Fractures de l’avant-bras – 3.5.1.1 Définition\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la prise en charge des fractures, l’ostéosynthèse se pratique sous anesthésie générale.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. La réduction chirurgicale se fait sous anesthésie générale à foyer ouvert, puis la fracture est fixée par un implant (broche, vis, plaque, clou) : c’est l’ostéosynthèse.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Fractures de la clavicule – méthode chirurgicale (diapo 24) ; Humérus – méthodes chirurgicales (diapo 44)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La tuméfaction dans la hernie étranglée est dure, irréductible, tendue, expansive et impulsive à la toux.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Dans la hernie étranglée, la tuméfaction est dure, tendue, douloureuse, irréductible mais NON impulsive et NON expansive à la toux.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – 4.2 Hernie compliquée (p. 108)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__10\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une dénivellation en marche d’escalier avec douleur exquise lorsqu’on palpe le membre est le signe d’une fracture de l’humérus.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La dénivellation en marche d’escalier avec douleur exquise à la palpation douce est le signe de la fracture de la clavicule.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Fractures de la clavicule – 3.2.2 Palpation\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__11\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une contusion abdominale par choc indirect se produit par percussion ou écrasement d’un organe contre la paroi abdominale postérieure.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. La percussion/l’écrasement correspond au choc direct. Le choc indirect est dû à la décélération brutale (collision, chute) qui étire, rompt ou arrache les moyens de fixité des viscères.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Contusions abdominales – 1.1 Mécanismes (p. 89-90)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__12\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L’épreuve ultime au lit du malade est le dernier verrou de sécurité à respecter avant toute transfusion sanguine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Le contrôle ultime pré-transfusionnel au lit du malade (vérification de l’identité et test de compatibilité ABO avec le sang du receveur et de la poche) est la dernière barrière contre l’accident ABO, réalisée juste avant de brancher la poche. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__13\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le signe de Psoas est la palpation douce du flanc gauche qui entraine une douleur controlatérale au cours des appendicites aigües.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Le signe du psoas est la douleur à la flexion forcée de la cuisse droite. La douleur en fosse iliaque droite provoquée par la palpation à gauche correspond au signe de Rovsing.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Appendicite – douleur provoquée (diapo 214) ; Prise en charge infirmière des pathologies chirurgicales L2 2025, formes cliniques (Rovsing, p. 115)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__14\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Sur les lieux d’un accident, l’infirmier peut tenter de réduire une fracture ouverte.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Faux. Devant une fracture ouverte : pas de manœuvres ni de mobilisations intempestives, surtout ne pas chercher à réduire ; nettoyer, faire un pansement stérile, immobiliser et transporter.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Intervention infirmière – 8.1.2 Fractures ouvertes\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__15\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les traumatismes du bassin, lors d’un choc antéro-postérieur, un ou les deux hémi-bassin s’ouvrent en rotation externe.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Compression antéro-postérieure : lors d’un impact antérieur, un ou deux hémi-bassins s’ouvrent en rotation externe (la compression latérale donne une rotation interne).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Traumatismes du bassin – 1.2.1 Mécanisme (p. 71)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__16\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fracture ouverte est une fracture qui communique avec l’extérieur par une plaie même minime.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Fracture ouverte : le foyer de fracture communique avec l’extérieur par une plaie même minime des parties molles.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – 5.2\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__17\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La primo-infection tuberculeuse se fait par voie aérienne et peut se disséminer par voie sanguine vers d’autres organes parmi lesquels le rachis.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. Dans le mal de Pott, le bacille de Koch arrive le plus souvent par voie sanguine à partir du complexe ganglio-pulmonaire (foyer de primo-infection), à la faveur d’une bacillémie.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Mal de Pott – II. Étiologie (diapo 170)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__18\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la majorité des cas de sciatalgie ou hernie discale, il s’agit d’un conflit disco-radiculaire.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Vrai. « Dans la majorité des cas il s’agit d’un conflit disco-radiculaire » ; la hernie discale est la cause de 80 % des sciatiques.\\n\\nSource : Neurochirurgie (livret), Sciatalgies / hernie discale – introduction (p. 24) II. QCM (Questions à choix multiple)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__19\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Reliez chaque processus de survenue des occlusions intestinales à son mécanisme (3 bonnes réponses).\\n| Processus | Mécanisme |\\n|---|---|\\n| 1- Occlusion organique | a- Obstruction |\\n| 2- Occlusion dynamique | b- Strangulation |\\n| 3- Occlusion mixte | c- Paralysie des muscles intestinaux |\\n| | d- Appendicite aigüe |\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(3, b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, d) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(2, c)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. (1, b) ; ; E. (3, d) ; ; F. (2, c)\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"L’occlusion organique (mécanique) se fait par obstruction ou strangulation (1-b). L’occlusion dynamique (fonctionnelle) est due au dérèglement nerveux avec paralysie (2-c). L’occlusion mixte (inflammatoire) survient au cours des affections septiques de voisinage, dont l’appendicite (3-d).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – étiologies 1.1 à 1.3 (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__20\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Reliez chaque mécanisme de survenue des occlusions intestinales à l’agent d’étranglement.\\n| Mécanisme | Agent d’étranglement |\\n|---|---|\\n| 1- Obstruction | a- Fécalome |\\n| 2- Strangulation | b- Invagination |\\n| 3- Paralysie des muscles intestinaux | c- Volvulus |\\n| | d- Tumeur |\\n| | e- Hypokaliémie |\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, d) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, c) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(3, e) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, d) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(2, a)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (1, d) ; ; B. (2, c) ; ; D. (3, e) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Obstruction : tumeur de la paroi, corps étranger, fécalome (1-d). Strangulation : volvulus, invagination (2-c). Occlusion fonctionnelle par paralysie : troubles métaboliques comme l’hypokaliémie (3-e). L’invagination n’est pas une obstruction (C faux), le fécalome n’est pas une strangulation (F faux).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – étiologies (p. 121-122)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__21\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, les complications immédiates d’une fracture sont : (3bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Lésions vasculaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cals vicieux\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pseudarthrose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Choc hypovolémique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Lésions nerveuses\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Ankylose.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Lésions vasculaires ; D. Choc hypovolémique ; E. Lésions nerveuses\",\n       \"answerLetters\": [\n        \"A\",\n        \"D\",\n        \"E\"\n       ],\n       \"explanation\": \"Complications immédiates : état de choc (traumatique/hémorragique), lésions cutanées, des parties molles, vasculaires et nerveuses. Cal vicieux, pseudarthrose et ankylose sont des complications secondaires ou tardives.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Généralités sur les fractures – VIII. Complications\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__22\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic positif de l’appendicite aigüe se fonde sur trois (3) de ces éléments, lesquels ? :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Douleurs fosse iliaque droite\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Hématurie terminale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Recherche des douleurs provoquées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pollakiurie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Hyperleucocytose à la NFS\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Douleurs fosse iliaque droite ; D. Recherche des douleurs provoquées ; F. Hyperleucocytose à la NFS\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Le diagnostic positif repose sur la douleur de la fosse iliaque droite, la douleur provoquée (Mac Burney…) avec défense, et biologiquement l’hyperleucocytose > 10 000/mm³. Hématurie et pollakiurie orientent vers l’appareil urinaire.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Appendicite – paracliniques et VIII. Diagnostic positif (p. 115-116)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__23\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type de fracture du fémur à son trait. (3 bonnes réponses) Type de fracture Trait de fracture Fracture du col du fémur Trait oblique, bas en dedans Fracture du trochanter Trait transversal, horizontal et vertical Trait transversal, oblique avec un 3ème fragment Fracture de la diaphyse fémorale osseux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(3, a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2, a) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(2, b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3, c)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. (1, b) ; ; D. (2, a) ; ; F. (3, c)\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Les fractures trochantériennes ont classiquement un trait oblique en bas et en dedans (2-a). Les fractures de la diaphyse ont des traits transversaux, obliques ou spiroïdes avec ou sans troisième fragment (3-c), ce que confirme le cours. Il reste pour le col le trait transversal/vertical (1-b). (trait des fractures du col et du trochanter : hors cours du projet) Remarque : Les lettres a, b, c du tableau ne sont pas imprimées dans le sujet ; elles correspondent à l’ordre des lignes.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Fractures de la diaphyse du fémur – II. Étiologie (diapo 65)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__24\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans l’examen somatique d’un traumatisé du bassin, quelles sont les associations qui ne sont pas vraies. (2 bonnes réponses) Symptôme Lésion 1.Le malade urine beaucoup et facilement avec des … a. Rupture vésicale\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(1, b) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2, d) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(4, a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2, b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(3, c) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3, a).\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. (2, b) ; ; F. (3, a).\",\n       \"answerLetters\": [\n        \"D\",\n        \"F\"\n       ],\n       \"explanation\": \"Repères du cours : la rupture de l’urètre donne une rétention d’urine avec globe vésical et impossibilité d’uriner ; la rupture de la vessie donne une absence de globe et une hématurie ; une lésion du rectum donne une rectorragie, une lésion du vagin des métrorragies. Les associations (2,b) et (3,a) sont celles qui contredisent ces repères. Remarque : Le tableau est presque illisible dans la capture (chargement en cours) : seule la première ligne est visible. L’explication ne peut pas être vérifiée ligne par ligne.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Traumatismes du bassin – complications immédiates\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__25\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces signes, quels sont ceux qui font suspecter un syndrome de VOLKMANN. (3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sueurs froides\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Œdème des extrémités\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cyanose\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Tachycardie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Insensibilité du membre atteint\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Pouls rapide, filant et imprenable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Œdème des extrémités ; C. Cyanose ; E. Insensibilité du membre atteint\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le syndrome de Volkmann se signale par la douleur, l’œdème (main gonflée), la cyanose (main violacée), la froideur des extrémités et des troubles sensitifs. Sueurs froides, tachycardie et pouls filant sont des signes de choc.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Syndrome de Wolkmann – 5.2 Étude clinique ; 7.1 Surveillance du plâtre\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__26\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le type de coma selon Glasgow chez un traumatisé du crâne qui n’ouvre pas les yeux, émet des sons incompréhensibles et fait des mouvements en extension à la douleur est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Traumatisme crânien modéré\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Traumatisme crânien dépassé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Traumatisme crânien grave\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Traumatisme crânien bénin\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Traumatisme crânien grave\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Yeux : aucune ouverture = 1 ; verbal : incompréhensible = 2 ; moteur : extension (décérébration) = 2. Total = 5, donc entre 3 et 8 : traumatisme crânien grave.\\n\\nSource : NEUROCHIRURGIE L3, diapos 17 à 23\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__27\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les fractures du fémur, le matin de l’intervention, l’intervention infirmière se résument à trois (3) de de ces activités, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire la préparation psychologique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Administrer l’anesthésique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Réaliser le bilan préopératoire complet\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Sonder le client sur prescription\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Prévenir le chirurgien en cas de fièvre\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Accompagner le client au bloc avec son dossier pour le rassurer.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"D. Sonder le client sur prescription ; E. Prévenir le chirurgien en cas de fièvre ; F. Accompagner le client au bloc avec son dossier pour le rassurer.\",\n       \"answerLetters\": [\n        \"D\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Le matin de l’intervention : sondage vésical, prémédication selon prescription, prévenir le chirurgien en cas de fièvre, accompagner le blessé au bloc avec son dossier complet. La préparation psychologique et le bilan se font avant, l’anesthésique relève de l’anesthésiste.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), 8.2.2.6 Les actes le matin de l’intervention\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__28\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Chez le traumatisé du membre supérieur, l’attitude Desault comprend trois (3) de ces signes, lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Épaule abaissée, projetée en avant ; rapprochée de la ligne médiane\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Abduction du bras et rotation externe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Tête inclinée du côté atteint et bras collé au corps\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Aplatissement du moignon de l’épaule\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Avant-bras semi-fléchi, soutenu par la main du côté opposé\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Crépitation osseuse\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Épaule abaissée, projetée en avant ; rapprochée de la ligne médiane ; C. Tête inclinée du côté atteint et bras collé au corps ; E. Avant-bras semi-fléchi, soutenu par la main du côté opposé\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Attitude de Desault : épaule abaissée, projetée en avant et rapprochée de la ligne médiane ; tête inclinée du côté atteint ; avant-bras demi-fléchi soutenu par la main opposée. L’abduction-rotation externe et l’aplatissement du moignon évoquent la luxation de l’épaule.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Fractures de la clavicule – 3.2.1 Inspection\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__29\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez trois (3) complications immédiates dans les polytraumatismes dans cette liste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Complications urinaires\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Hémorragies\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Nécrose ischémique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Coxarthrose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Fractures associées\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Ankylose\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Complications urinaires ; B. Hémorragies ; E. Fractures associées\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"Chez le polytraumatisé, on redoute d’emblée le choc hémorragique, les lésions urinaires (rupture vésicale ou urétrale, notamment avec les fractures du bassin) et les lésions associées passées inaperçues (fractures, luxations). Nécrose, coxarthrose et ankylose sont des complications tardives.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Polytraumatisé et Traumatismes du bassin – complications immédiates\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__30\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez trois (3) gestes à réaliser si vous vous retrouviez sur les lieux d’un accident.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire la prémédication\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Baliser les lieux en vue de protéger le blessé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Transporter le blessé sur votre engin ou dans votre véhicule\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Mettre en route une perfusion\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Mettre le blessé en position latérale de sureté ou sécurité\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Faire une immobilisation provisoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Baliser les lieux en vue de protéger le blessé ; E. Mettre le blessé en position latérale de sureté ou sécurité ; F. Faire une immobilisation provisoire\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Sur les lieux : protéger (baliser), assurer la liberté des voies aériennes en position latérale de sécurité, immobiliser les fractures (attelle, gouttière). Le transport sur un engin personnel est à proscrire ; la prémédication relève du bloc.\\n\\nSource : Traumatologie complet (chirurgie traumatologique et orthopédique), Conduite à tenir auprès d’un traumatisé des voies publiques – gestes salvateurs (balisage : hors cours)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__31\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi ces symptômes, indiquez trois (3) indications du drainage.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Dilatation des bronches\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Appendicite aigüe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Méningite purulente\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Cancer de la vessie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pleurésies purulentes\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Cavités infectées\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Dilatation des bronches ; E. Pleurésies purulentes ; F. Cavités infectées\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Le drainage sert à évacuer une collection : épanchements pleuraux (pleurésie purulente, hémothorax), cavités infectées (abcès), et drainage de posture des sécrétions bronchiques (dilatation des bronches). L’appendicite se traite par appendicectomie. (explication partiellement hors cours du projet)\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Traumatisme du thorax – drainage des épanchements pleuraux (diapo 17) ; Prise en charge infirmière des pathologies chirurgicales L2 2025, drainage de posture (p. 50)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__32\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, indiquez trois (3) contre-indications de transfusion sanguine.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hypertension artérielle\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Diabète\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Insuffisance rénale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Anémie chronique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Insuffisance cardiaque\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Œdème aigu du poumon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Hypertension artérielle ; E. Insuffisance cardiaque ; F. Œdème aigu du poumon\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"L’apport de volume expose à la surcharge volémique, avec œdème aigu du poumon ; il est donc dangereux en cas d’HTA, d’insuffisance cardiaque ou d’OAP. L’anémie est au contraire une indication. (explication partiellement hors cours du projet)\\n\\nSource : Initiation à la réanimation L2 2025, complications du remplissage vasculaire (p. 42)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__33\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La surveillance d’un appareillage de drainage consiste à trois (3) de ces activités, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vérifier la perméabilité du drain\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Vider le contenu du bocal quotidiennement à heure fixe\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Surveiller l’abondance de l’écoulement\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Surveiller l’abondance et noter la quantité du liquide sur une feuille de température\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveiller les paramètres vitaux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Vérifier la dépression créée par l’aspiration et la régler au besoin.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Vérifier la perméabilité du drain ; C. Surveiller l’abondance de l’écoulement ; F. Vérifier la dépression créée par l’aspiration et la régler au besoin.\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"F\"\n       ],\n       \"explanation\": \"Surveillance des drains : vérifier leur vide/aspiration et leur bonne fixation, l’écoulement (quantité, couleur, aspect), ne jamais laisser un drain bouché ; en drainage aspiratif, maintenir le vide dans les flacons.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, surveillance des redons (p. 49-50) ; Cours de chirurgie traumatique et digestif (L2), Péritonites – soins des drains (diapo 244)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__34\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Trois (3) de ces tâches ci-dessous font référence à la préparation psychologique avant toute intervention chirurgicale. Ce sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Evaluer l’état physique, nutritionnel et biologique du client\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rassurer le client et le mettre en confiance\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Prévenir et lutter contre l’infection\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Procéder à la prémédication\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Dissiper ses craintes de l’intervention ou même de la mort\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Lui donner tous les détails de l’intervention\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Rassurer le client et le mettre en confiance ; E. Dissiper ses craintes de l’intervention ou même de la mort ; F. Lui donner tous les détails de l’intervention\",\n       \"answerLetters\": [\n        \"B\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"La préparation psychologique vise à réduire l’anxiété : rassurer le blessé souvent effrayé, dissiper ses craintes et lui fournir des informations sur la période péri-opératoire. Bilan, prévention de l’infection et prémédication relèvent de la préparation physique. Remarque : Le cours parle d’« informations sur la période péri-opératoire » plutôt que de « tous les détails de l’intervention ».\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Fémur – soins préopératoires (diapo 73) ; Appendicite – objectifs des soins (diapo 218)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__35\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Deux (2) complications courantes de la péritonite sont sur cette liste, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Hémorragie intra abdominale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Occlusion abdominale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Septicémie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ulcère gastroduodénal\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pancréatite aigüe\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Salpingite\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Occlusion abdominale ; D. Ulcère gastroduodénal\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La péritonite évolue vers l’iléus paralytique : « à la péritonite s’est ajoutée l’occlusion paralytique ». L’infection peut aussi se généraliser (septicémie).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Péritonites – formes cliniques et physiopathologie (p. 131-132)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__36\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Trois (3) tâches en tant qu’infirmier auprès d’un opéré en salle d’hospitalisation après le bloc opératoire sont dans cette liste, lesquelles ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Surveillance des paramètres\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Evaluer l’état physique, nutritionnel et biologique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Administrer le traitement prescrit\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Préparer psychologiquement la cliente\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Surveiller la plaie opératoire et les drains\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Préparer le champ opératoire\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Surveillance des paramètres ; C. Administrer le traitement prescrit ; E. Surveiller la plaie opératoire et les drains\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"En post-opératoire : surveillance des constantes, administration du traitement prescrit, surveillance de la plaie opératoire et des drains. Évaluation, préparation psychologique et préparation du champ sont des soins pré-opératoires.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Cancer de l’œsophage – soins post-opératoires (diapo 254)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__37\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les deux (2) buts du traitement de l’occlusion intestinale sont :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Lutter contre la fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Rétablir la continuité du circuit intestinal normal\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Lever l’obstacle\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Alimenter le client\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Corriger les désordres humoraux\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Assurer une couverture antibiotique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Lever l’obstacle ; E. Corriger les désordres humoraux\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"« Le traitement des occlusions intestinales aiguës comporte une double action : la correction des déséquilibres humoraux et la suppression de l’obstacle. »\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – VI. Traitement (p. 126)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__38\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous auriez à poser trois (3) gestes entant qu’infirmier avant l’entrée d’un client au bloc opératoire. Lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Demande de bilan sanguin\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Procéder à la réanimation médicale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Pose de sonde nasogastrique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Faire le pansement\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Pose de sonde urinaire\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Absorption de la cavité abdominale\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Demande de bilan sanguin ; C. Pose de sonde nasogastrique ; E. Pose de sonde urinaire\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Gestes d’urgence avant l’intervention : prélever le sang pour bilan et groupage, mettre en place une sonde gastrique (éviter vomissements et syndrome de Mendelson) et une sonde urinaire (diurèse horaire).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Occlusions – gestes d’urgence (p. 126) ; Contusions abdominales – moyens médicaux (p. 95-96)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__39\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Indiquez deux (2) complications de la hernie étranglée dans cette liste.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Insuffisance rénale\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Insuffisance hépatique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Occlusion intestinale\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Appendicite aigüe\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Péritonite aigüe\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Occlusion intestinale ; E. Péritonite aigüe\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L’étranglement provoque arrêt des matières et des gaz et vomissements (occlusion), puis ischémie, sphacèle et perforation du viscère hernié (péritonite).\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Hernies – 4.2 Étranglement herniaire (p. 107-108)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__40\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au cours des contusions abdominales, le choc direct se produit par :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Contre coup produisant des lésions à distance des organes intra abdominaux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Percussion ou écrasement d’un organe contre les vertèbres\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"En cas d’accélération ou décélération\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Par effet explosif causé par augmentation soudaine de la pression intra abdominale responsable de multiples lésions.\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Percussion ou écrasement d’un organe contre les vertèbres\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Choc direct : percussion déterminant éclatement, dilacération ou écrasement ; les viscères creux s’écrasent entre la saillie du rachis et la ceinture pelvienne. L’accélération/décélération correspond au choc indirect.\\n\\nSource : Prise en charge infirmière des pathologies chirurgicales L2 2025, Contusions – mécanismes (p. 89) ; Cours de chirurgie traumatique et digestif (L2), diapo 182\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__41\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les signes fonctionnels des traumatismes crânio-encéphaliques sont : (Choisissez trois (3) bonnes réponses).\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Perte de connaissance initiale ou coma d’emblée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Plaie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Douleur\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Ecchymose\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Amnésie\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Hématome\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Perte de connaissance initiale ou coma d’emblée ; C. Douleur ; E. Amnésie\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Le TC entraîne un dysfonctionnement cérébral : perte de connaissance, céphalée (douleur), amnésie post-traumatique, coma. Plaie, ecchymose et hématome sont des signes physiques (examen du crâne).\\n\\nSource : NEUROCHIRURGIE L3, introduction (diapo 4) et signes physiques (diapo 16) ; Neurochirurgie (livret), p. 54 (amnésie = signe fonctionnel)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__42\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le traumatisme crânien modéré, le score de Glasgow est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"9 à 12\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"13 à 15\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3 à 8\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 9 à 12\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Glasgow 9 à 12 = traumatisme modéré ; 13 à 15 = bénin ; 3 à 8 = grave.\\n\\nSource : NEUROCHIRURGIE L3, diapo 23\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__43\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans cette liste, choisissez deux bonnes affirmations\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La monoplégie est la présence de mouvement d’intensité moindre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La paraplégie est une paralysie des deux membres inférieurs\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La tétraplégie est une paralysie des quatre membres\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La parésie est une présence de mouvement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La paraplégie est une paralysie des deux membres inférieurs ; C. La tétraplégie est une paralysie des quatre membres\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\"\n       ],\n       \"explanation\": \"Paraplégie = paralysie des deux membres inférieurs ; tétraplégie = paralysie des quatre membres (atteinte cervicale). La monoplégie est la paralysie d’un seul membre ; la parésie est une paralysie incomplète (diminution de la force), pas un mouvement normal.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Fractures du rachis – symptômes neurologiques (diapo 152)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__44\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type d’hémorragie cérébrale au type d’intervalle libre. (Choisissez 3 bonnes réponses) Type d’hémorragie cérébrale Type d’intervalle libre 1-Hémorragie Epidurale a- Long intervalle libre. 2-Hémorragie sous durale b- Bref intervalle libre 3-Hémorragie intra crânienne c- Absence d’intervalle libre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(3,c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2,a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1,a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2,b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(1,b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3,b)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (3,c) ; ; B. (2,a) ; ; E. (1,b) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"B\",\n        \"E\"\n       ],\n       \"explanation\": \"L’hématome extradural (épidural) se révèle après un intervalle libre ; l’hématome intradural (sous-dural) se distingue par « la grande durée de l’intervalle libre ». L’hémorragie intracérébrale entraîne des troubles d’emblée, sans intervalle libre.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Traumatismes crâniens – VI. Épanchements sanguins (diapos 112-113)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__45\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Associez chaque type d’hémorragie cérébrale à l’origine du sang. (Choisissez 3 bonnes réponses) Type d’hémorragie cérébrale Origine du sang 1-Hémorragie Epidurale a-sang artériel méningé 2-Hémorragie sous durale b- sang veineux 3-Hémorragie intra crânienne c-pétéchies ou gros hématomes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"(3,c) ;\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"(2,a) ;\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"(1,a) ;\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"(2,b) ;\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"(1,b) ;\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"(3,b)\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. (3,c) ; ; C. (1,a) ; ; D. (2,b) ;\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\",\n        \"D\"\n       ],\n       \"explanation\": \"L’hématome extradural vient le plus souvent d’une artère méningée (artère méningée moyenne) ; l’hématome sous-dural, des veines entre cerveau et dure-mère ; l’hémorragie intracérébrale réalise des pétéchies ou un gros hématome dans le parenchyme. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__46\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Ces signes sont ceux de la meilleure réponse verbale du score de GLASGOW, exceptés deux (2), lesquels ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Confuse\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Spontanée\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Appropriée\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Flexion anormale\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Incohérente\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Spontanée ; D. Flexion anormale\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La réponse verbale se cote : appropriée/orientée, confuse, incohérente, incompréhensible, aucune. « Spontanée » appartient à l’ouverture des yeux, « flexion anormale » à la réponse motrice.\\n\\nSource : NEUROCHIRURGIE L3, diapos 17 à 21 Étude de cas\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__47\",\n       \"num\": \"49\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"La quantité de solutés indispensable à M. TINTO le premier jour selon Baxter est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8000 ml\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Baxter : J1 = poids × 4 × SCB ; J2 = moitié de J1. Total 2 jours = 1,5 × J1 = 12 000 ml, donc J1 = 8 000 ml (vérification : 57 × 4 × 35 = 7 980 ≈ 8 000 ml).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 2 – 5.3 Réanimation hydroélectrolytique (règle de Baxter)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__48\",\n       \"num\": \"50\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"La quantité de solutés pour la réanimation de M. TINTO le deuxième jour selon Baxter est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"12000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 4000 ml\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"J2 = ½ de J1 = 8 000 / 2 = 4 000 ml (et 8 000 + 4 000 = 12 000 ml, comme dans l’énoncé).\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 2 – règle de Baxter\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__49\",\n       \"num\": \"51\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le poids de M. TINTO est de :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"28 Kg\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"57 Kg\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"85 Kg\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"42 Kg\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 57 Kg\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le poids se déduit de Baxter : J1 = 8 000 ml = P × 4 × 35, d’où P = 8 000 / 140 ≈ 57 kg. Remarque : Le poids n’est pas écrit dans l’énoncé (57 y est l’âge) : il se calcule à partir des 12 000 ml prescrits.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 2 – règle de Baxter\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__50\",\n       \"num\": \"52\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Au cours de la première journée, les quantités de macromolécules, de glucosé et de bicarbonate à 14p.1000 sont : (Choisissez 3 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"3000 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"2000 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"6000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"8000 ml\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"4000 ml\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"1000 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 3000 ml ; E. 4000 ml ; F. 1000 ml\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\",\n        \"F\"\n       ],\n       \"explanation\": \"Les 8 000 ml du J1 se répartissent en 3 000 ml de macromolécules, 4 000 ml de glucosé et 1 000 ml de bicarbonate (3 000 + 4 000 + 1 000 = 8 000). Le cours (règle d’Evans) prévoit aussi des grosses molécules, et pour les cristalloïdes ¼ de bicarbonate et ¾ de glucosé. (répartition exacte du J1 : hors cours du projet)\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – réanimation du premier jour (règle d’Evans)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__51\",\n       \"num\": \"53\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le débit du sérum glucosé isotonique 5%(SGI) au deuxième jour selon sachant que toute la quantité doit passer en 8 heures est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"62 gouttes/mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"83 gouttes/mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"160 gouttes/mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"46 gouttes/mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 62 gouttes/mn\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Débit (gouttes/min) = volume (ml) × 20 / durée (min). 62 gouttes/min en 8 h (480 min) correspond à environ 1 500 ml de SGI au J2. (calcul hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__52\",\n       \"num\": \"54\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"L’interne décide que le taux d’hémoglobine du client soit ramené à 10 g/dl de sang après la transfusion en 2 heures et demie. La quantité de sang envisagée selon le type de sang disponible à la banque de sang est : (Choisissez 2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"855 ml\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1050 ml\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"3000 ml\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1800 ml\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"2800 ml\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"1710 ml\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 855 ml ; F. 1710 ml\",\n       \"answerLetters\": [\n        \"A\",\n        \"F\"\n       ],\n       \"explanation\": \"Gain voulu : 10 − 5 = 5 g/dl. Formules usuelles : culot globulaire = 3 × poids × ΔHb = 3 × 57 × 5 = 855 ml ; sang total = 6 × poids × ΔHb = 6 × 57 × 5 = 1 710 ml. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__53\",\n       \"num\": \"55\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Les débits de la transfusion selon le sang utilisé seront de : (Choisissez 2 bonnes réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"171 gouttes/mn\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"100 gouttes/mn\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"85 gouttes/mn\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"70 gouttes/mn\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"280 gouttes/mn\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"140 gouttes/mn\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. 171 gouttes/mn ; C. 85 gouttes/mn\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Durée : 2 h 30 = 150 min ; transfuseur ≈ 15 gouttes/ml. Sang total : 1 710 × 15 / 150 = 171 gouttes/min ; culot : 855 × 15 / 150 ≈ 85 gouttes/min. (explication hors cours du projet)\\n\\nSource : aucune source trouvée dans les cours du projet\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__54\",\n       \"num\": \"56\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le chiffre qui permet d’évaluer le pronostic vital chez M. TINTO selon la loi de Baux est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"72\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"107\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"92\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"84\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 107\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La loi de Baux additionne l’âge et le pourcentage de surface brûlée pour estimer le pronostic vital.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – 5.5 Pronostic\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__55\",\n       \"num\": \"57\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Le pronostic vital selon la loi de Baux de M. TINTO est :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Guérison certaine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Mort quasi-certaine\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"50% de chance de guérir ou de mourir\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Mort quasi-certaine\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Selon le cours : somme < 50 → guérison très probable ; > 100 → mort quasi certaine ; entre 50 et 100 → une chance sur deux. Avec 107, le pronostic est une mort quasi certaine.\\n\\nSource : Pathologie chirurgicale – Sémiologie L1, Brûlures 1 – 5.5 Pronostic\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-chir-j4-ide__56\",\n       \"num\": \"58\",\n       \"type\": \"CAS_CLINIQUE\",\n       \"typeLabel\": \"Étude de cas / Cas clinique\",\n       \"partieTitle\": \"Cas clinique\",\n       \"caseTitle\": \"Cas clinique\",\n       \"caseData\": \"Cas clinique : Étude de cas. Vous êtes infirmier diplômé d’État au service des grands brûlés du CHU de Cocody à Abidjan. A votre garde, vous recevez Monsieur Belem TINTO, 57 ans, domicilié au quartier Mossikro dans la commune d’Attécoubé et propriétaire d’une maison de transfert de devise. Il est aussi suivi pour diabète à l’INSP d’Adjamé. Il est reçu dans votre service pour brûlure par électrocution. L’examen clinique pratiqué par l’interne de service évalue les lésions à 35% de la surface corporelle de M. TINTO selon la table de Lund et Browder. Pendant l’exploration des différents appareils chez M. BELEM, l’interne de service découvre une hypertrophie bénigne de la prostate. En outre, l’examen de laboratoire révèle un taux d’hémoglobine à 5g/dl de sang. En outre, M. BELEM demande avec insistance la présence de sa secrétaire particulière afin de lui donner des directives pour un meilleur fonctionnement de son entreprise. L’interne institue une réanimation médicale basée sur le remplissage vasculaire de solutés avec une quantité estimée à 12 000 ml les deux premiers jours de la prise en charge en fonction de la surface corporelle brûlée.\",\n       \"text\": \"Identifier trois (3) signes cardinaux qui ont permis la découverte de l’hypertrophie prostatique de Monsieur TINTO :\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Anorexie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Pollakiurie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Dysurie\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Céphalées\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Rétention d’urine\"\n        },\n        {\n         \"letter\": \"F\",\n         \"text\": \"Diarrhées\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Pollakiurie ; C. Dysurie ; E. Rétention d’urine\",\n       \"answerLetters\": [\n        \"B\",\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"L’adénome de la prostate comprime l’urètre : dysurie (premier symptôme), pollakiurie nocturne/diurne, et rétention d’urine (aiguë ou chronique) ; l’adénome est la première cause de rétention. Remarque : la capture s’arrête au début d’une dernière question (en-tête « Incorrect » visible, énoncé et options absents). Elle n’a pas pu être transcrite.\\n\\nSource : Cours de chirurgie traumatique et digestif (L2), Adénome de la prostate – clinique (diapo 288) ; Rétention urinaire – étiologies (diapo 306)\",\n       \"sourceDoc\": \"Révision J1 à J4 IDE/SFM — corrigé expliqué (J4 Chirurgie)\",\n       \"sourceFile\": \"REVISION_J1_a_J4_IDE_SFM_Corrige_explique.docx\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
